<?php $statusLabels=['available'=>'Disponible','laundry'=>'Au lavage','repair'=>'A reparer','unavailable'=>'Indisponible','archived'=>'Archive'];$maxLabel=max([1,...array_map(static fn($r)=>(int)$r['total'],$labels)]);$maxWear=max([1,...array_map(static fn($r)=>(int)$r['wears'],$wearFrequency)]); ?>
<section class="welcome-row"><div><p class="eyebrow">VOTRE ESPACE, VOTRE STYLE</p><h1>Bonjour <?= e(explode(' ',$user['full_name'])[0]) ?> <span class="wave">&#10022;</span></h1><p class="subheading">Tout ce que vous aimez porter, reuni au meme endroit.</p></div><a class="button primary" href="<?= e(url('clothes-create')) ?>">+ Ajouter une piece</a></section>
<section class="stat-grid"><?php foreach($labels as $row): ?><article class="stat-card"><span class="stat-number"><?= e($row['total']) ?></span><span class="stat-title"><?= e($row['name']) ?></span><div class="bar-track"><i style="width:<?= round((int)$row['total']/$maxLabel*100) ?>%"></i></div></article><?php endforeach; ?><article class="stat-card"><span class="stat-number"><?= e($outfitCount) ?></span><span class="stat-title">Tenues composees</span><a href="<?= e(url('outfits')) ?>">Voir mes tenues &rarr;</a></article></section>
<div class="analytics-grid"><article class="analytics-panel"><p class="eyebrow">ETAT DES PIECES</p><h2>Disponibilite</h2><?php foreach($statusLabels as $key=>$label): ?><div class="metric-row"><span><?= e($label) ?></span><b><?= e($statuses[$key]??0) ?></b></div><?php endforeach; ?></article><article class="analytics-panel"><p class="eyebrow">FINANCES</p><h2>Ce mois-ci</h2><h3>Depenses</h3><?php if(!$monthSpend): ?><p class="subheading">Aucune depense enregistree ce mois-ci.</p><?php else: foreach($monthSpend as $r): ?><div class="metric-row"><span><?= e($r['currency']) ?></span><b><?= e(number_format((float)$r['total'],2,',',' ')) ?></b></div><?php endforeach; endif; ?><h3>Valeur de la garde-robe</h3><?php foreach($wardrobeValue as $r): ?><div class="metric-row"><span><?= e($r['currency']) ?></span><b><?= e(number_format((float)$r['total'],2,',',' ')) ?></b></div><?php endforeach; ?><h3>Budgets en cours</h3><?php if(!$budgets): ?><p class="subheading">Aucun budget actif.</p><?php else: foreach($budgets as $b): ?><div class="metric-row"><span><?= e($b['name']) ?></span><b><?= e(number_format(max(0,(float)$b['amount']-(float)$b['spent']),2,',',' ')) ?> <?= e($b['currency']) ?> restants</b></div><?php endforeach; endif; ?></article></div>
<div class="analytics-grid"><article class="analytics-panel"><p class="eyebrow">A VENIR</p><h2>Calendrier</h2><?php if(!$upcoming): ?><p class="subheading">Aucune tenue planifiee.</p><?php else: foreach($upcoming as $event): ?><div class="metric-row"><span><?= e(date('d/m',strtotime($event['event_date']))) ?> · <a href="<?= e(url('outfits-show',['id'=>$event['outfit_id']])) ?>"><?= e($event['outfit_name']) ?></a></span><b><a href="<?= e(url('calendar',['month'=>substr($event['event_date'],0,7)])) ?>">Voir</a></b></div><?php endforeach; endif; ?><a class="text-link" href="<?= e(url('calendar')) ?>">Ouvrir le calendrier &rarr;</a></article><article class="analytics-panel"><p class="eyebrow">FREQUENCE D'USAGE</p><h2>Pieces les plus portees</h2><?php foreach($wearFrequency as $r): ?><div class="bar-row"><span><?= e($r['name']) ?></span><div class="bar-track"><i style="width:<?= round((int)$r['wears']/$maxWear*100) ?>%"></i></div><b><?= e($r['wears']) ?></b></div><?php endforeach; ?></article></div>
<section class="activity-grid"><article><div class="section-head"><div><p class="eyebrow">AJOUTS RECENTS</p><h2>Dernieres pieces</h2></div><a class="text-link" href="<?= e(url('clothes')) ?>">Tout voir &rarr;</a></div><?php if(!$recentClothes): ?><p class="subheading">Votre garde-robe commence ici.</p><?php else: foreach($recentClothes as $item): ?><a class="search-result" href="<?= e(url('clothes-show',['id'=>$item['id']])) ?>"><b><?= e($item['name']) ?></b><span><?= e($item['label_name']) ?></span><i>&rarr;</i></a><?php endforeach; endif; ?></article><article><div class="section-head"><div><p class="eyebrow">TENUES ET ACTIVITE</p><h2>Dernieres tenues</h2></div><a class="text-link" href="<?= e(url('outfits')) ?>">Tout voir &rarr;</a></div><?php if(!$recentOutfits): ?><p class="subheading">Aucune tenue composee pour le moment.</p><?php else: foreach($recentOutfits as $item): ?><a class="search-result" href="<?= e(url('outfits-show',['id'=>$item['id']])) ?>"><b><?= e($item['name']) ?></b><span><?= e(date('d/m/Y',strtotime($item['created_at']))) ?></span><i>&rarr;</i></a><?php endforeach; endif; ?><h3>Dernieres tenues portees</h3><?php foreach($recentWears as $item): ?><div class="metric-row"><a href="<?= e(url('outfits-show',['id'=>$item['id']])) ?>"><?= e($item['name']) ?></a><span><?= e(date('d/m/Y',strtotime($item['worn_at']))) ?></span></div><?php endforeach; ?></article></section>